//! The differential harness (1.5.0): the binary against the Python
//! reference's verdicts and reason codes. A difference is a bug in one of
//! them, resolved against the spec.
//!
//! * the shared suites in `tests/fixtures` (generated by the reference) and
//!   the anchors fixture (`scripts/generate_anchor_vectors.py`) always run;
//! * `GM_VERIFY_CORPUS=<file>` also runs the core's verification corpus
//!   (`scripts/export_reference_corpus.py --suite verification`): one suite
//!   (`{"suite", "vectors"}`), a list of them, or `{"suites": [...]}`.
//!   Vectors without an adapter are reported as skipped; with
//!   `GM_VERIFY_CORPUS_STRICT=1` a skip fails the run.
//!
//! `GM_VERIFY_BINARY=<path>` runs another build of the binary, such as a
//! static release binary.

mod adapter;
mod common;

use adapter::{adapt, expected, project, Adapted};
use common::{fixture, run, Scratch};
use serde_json::Value;

#[derive(Default)]
struct Tally {
    ran: usize,
    skipped: Vec<String>,
    failed: Vec<String>,
}

fn run_suite(suite: &Value, tally: &mut Tally) {
    let name = suite["suite"].as_str().unwrap_or("unnamed");
    for v in suite["vectors"].as_array().into_iter().flatten() {
        let id = format!("{name}/{}", v["id"].as_str().unwrap_or("?"));
        let scratch = Scratch::new(name);
        let case = match adapt(name, v, &scratch) {
            Adapted::Run(case) => case,
            Adapted::Skip(why) => {
                tally.skipped.push(format!("{id}: {why}"));
                continue;
            }
        };
        let result = run(&case.args);
        tally.ran += 1;
        // The exit code is the verdict.
        if let Ok(out) = serde_json::from_str::<Value>(&result.stdout) {
            if let Some(verified) = out["verified"].as_bool() {
                if (result.code == 0) != verified {
                    tally.failed.push(format!(
                        "{id}: exit code {} for verified={verified}",
                        result.code
                    ));
                }
            }
        }
        let (want, got) = (expected(&case), project(&case, &result));
        if want != got {
            tally
                .failed
                .push(format!("{id}:\n  expected {want}\n  got      {got}"));
        }
    }
}

fn suites(corpus: Value) -> Vec<Value> {
    match corpus {
        Value::Array(suites) => suites,
        Value::Object(ref map) if map.contains_key("suites") => {
            map["suites"].as_array().cloned().unwrap_or_default()
        }
        other => vec![other],
    }
}

#[test]
fn the_binary_gives_the_reference_verdicts_on_the_shared_vectors() {
    let mut tally = Tally::default();
    for name in [
        "canonical",
        "field_registry",
        "out_of_band",
        "remediation",
        "anchors",
    ] {
        run_suite(&fixture(name), &mut tally);
    }
    assert!(tally.failed.is_empty(), "{}", tally.failed.join("\n"));
    // Every decision, export and record vector, and every anchored export;
    // the canonical-JSON, timestamp, agreement and anchor-chain vectors are
    // not the binary's (the anchor chains are the SDK's tests/anchors.rs).
    assert_eq!(tally.ran, 10 + 6 + 41 + 31 + 8, "{:#?}", tally.skipped);
}

#[test]
fn the_binary_verifies_the_reference_export_as_the_na_did() {
    let v = fixture("python-vectors");
    let scratch = Scratch::new("python-vectors");
    let result = run(&[
        "export",
        &scratch.file("export.jsonl", v["export"].as_str().unwrap()),
        "--na-key",
        v["na_public_key"].as_str().unwrap(),
        "--executor-keys",
        &scratch.json("keys.json", &v["executor_keys"]),
        "--json",
    ]);
    assert_eq!(result.code, 0, "{}", result.stdout);
    assert_eq!(result.json(), v["server_verification"]);
}

#[test]
fn the_core_corpus_when_given() {
    let Some(path) = std::env::var_os("GM_VERIFY_CORPUS") else {
        eprintln!("GM_VERIFY_CORPUS is not set: the core's verification corpus is not run");
        return;
    };
    let text = std::fs::read_to_string(&path).expect("the corpus is readable");
    let corpus: Value = serde_json::from_str(&text).expect("the corpus is JSON");
    let mut tally = Tally::default();
    for suite in suites(corpus) {
        run_suite(&suite, &mut tally);
    }
    eprintln!(
        "corpus: {} vectors ran, {} skipped",
        tally.ran,
        tally.skipped.len()
    );
    for skipped in &tally.skipped {
        eprintln!("  skipped {skipped}");
    }
    assert!(tally.failed.is_empty(), "{}", tally.failed.join("\n"));
    let strict = std::env::var("GM_VERIFY_CORPUS_STRICT").is_ok_and(|s| s == "1");
    assert!(
        !strict || tally.skipped.is_empty(),
        "{} vectors have no adapter",
        tally.skipped.len()
    );
    assert!(tally.ran > 0, "the corpus holds no vector the binary runs");
}
